function generateExecutiveSummary(analyses) {
  const totalVolume = analyses.reduce((sum, analysis) => 
    sum + (analysis.overview?.totalVolume || 0), 0
  );

  const avgMarketHealth = analyses.reduce((sum, analysis) => {
    const health = analysis.overview?.marketHealth || {};
    const healthScore = (health.liquidity + health.efficiency + health.participation) / 3;
    return sum + healthScore;
  }, 0) / analyses.length;

  const totalOpportunities = analyses.reduce((sum, analysis) => 
    sum + (analysis.opportunityAnalysis?.length || 0), 0
  );

  const highRiskCount = analyses.reduce((sum, analysis) => 
    sum + (analysis.riskAssessment?.filter(r => r.severity > 0.7)?.length || 0), 0
  );

  return {
    totalMarketVolume: totalVolume,
    averageMarketHealth: avgMarketHealth,
    opportunitiesIdentified: totalOpportunities,
    highRiskItems: highRiskCount,
    marketSentiment: avgMarketHealth > 0.7 ? 'positive' : avgMarketHealth > 0.4 ? 'neutral' : 'negative',
    keyInsights: extractKeyInsights(analyses)
  };
}

function generateCrossRegionalInsights(analyses) {
  const regionalData = analyses.reduce((acc, analysis) => {
    const region = analysis.task.region;
    acc[region] = {
      volume: analysis.overview?.totalVolume || 0,
      transactions: analysis.overview?.totalTransactions || 0,
      health: analysis.overview?.marketHealth || {}
    };
    return acc;
  }, {});

  return {
    volumeDistribution: Object.entries(regionalData).map(([region, data]) => ({
      region,
      volume: data.volume,
      percentage: (data.volume / Object.values(regionalData).reduce((sum, d) => sum + d.volume, 0)) * 100
    })),

    healthComparison: Object.entries(regionalData).map(([region, data]) => ({
      region,
      healthScore: ((data.health.liquidity || 0) + (data.health.efficiency || 0) + (data.health.participation || 0)) / 3
    })),

    arbitrageOpportunities: identifyRegionalArbitrageOpportunities(regionalData)
  };
}

function generateMarketHealthDashboard(analyses) {
  const healthMetrics = analyses.map(analysis => ({
    region: analysis.task.region,
    timeRange: analysis.task.timeRange,
    ...analysis.overview?.marketHealth
  }));

  return {
    overallHealthScore: healthMetrics.reduce((sum, metric) => {
      const score = (metric.liquidity + metric.efficiency + metric.participation) / 3;
      return sum + score;
    }, 0) / healthMetrics.length,

    healthTrends: calculateHealthTrends(healthMetrics),

    healthByRegion: healthMetrics.reduce((acc, metric) => {
      if (!acc[metric.region]) acc[metric.region] = [];
      acc[metric.region].push(metric);
      return acc;
    }, {}),

    healthFactors: {
      liquidity: { average: healthMetrics.reduce((sum, m) => sum + (m.liquidity || 0), 0) / healthMetrics.length },
      efficiency: { average: healthMetrics.reduce((sum, m) => sum + (m.efficiency || 0), 0) / healthMetrics.length },
      participation: { average: healthMetrics.reduce((sum, m) => sum + (m.participation || 0), 0) / healthMetrics.length }
    }
  };
}

function extractTopOpportunities(analyses) {
  const allOpportunities = analyses.flatMap(analysis => analysis.opportunityAnalysis || []);

  return allOpportunities
    .sort((a, b) => (b.confidence || 0) - (a.confidence || 0))
    .slice(0, 15)
    .map(opportunity => ({
      ...opportunity,
      sourceRegion: analyses.find(a => a.opportunityAnalysis?.includes(opportunity))?.task.region
    }));
}

function extractCriticalRisks(analyses) {
  const allRisks = analyses.flatMap(analysis => analysis.riskAssessment || []);

  return allRisks
    .filter(risk => risk.severity > 0.6)
    .sort((a, b) => b.severity - a.severity)
    .slice(0, 10)
    .map(risk => ({
      ...risk,
      sourceRegion: analyses.find(a => a.riskAssessment?.includes(risk))?.task.region
    }));
}

function consolidatePredictions(analyses) {
  return {
    shortTerm: consolidatePredictionType(analyses, 'shortTerm'),
    mediumTerm: consolidatePredictionType(analyses, 'mediumTerm'),
    longTerm: consolidatePredictionType(analyses, 'longTerm'),
    consensusForecast: generateConsensusForecast(analyses)
  };
}

function consolidateRecommendations(analyses) {
  const allRecommendations = analyses.flatMap(analysis => analysis.recommendations || []);

  // Group by type and prioritize
  const groupedRecommendations = allRecommendations.reduce((acc, rec) => {
    if (!acc[rec.type]) acc[rec.type] = [];
    acc[rec.type].push(rec);
    return acc;
  }, {});

  return {
    immediate: extractImmediateRecommendations(allRecommendations),
    shortTerm: extractShortTermRecommendations(allRecommendations),
    longTerm: extractLongTermRecommendations(allRecommendations),
    byType: groupedRecommendations
  };
}

