  });

  // Return top 5 most significant insights
  return insights
    .sort((a, b) => {
      const severityOrder = { 'critical': 4, 'high': 3, 'warning': 2, 'info': 1 };
      return (severityOrder[b.severity] || 0) - (severityOrder[a.severity] || 0);
    })
    .slice(0, 5);
}

