  }
}];

function identifyFocusAreasForNextRun(report) {
  const focusAreas = [];

  // Focus on regions with poor market health
  Object.entries(report.marketHealthDashboard.healthByRegion).forEach(([region, healthData]) => {
    const avgHealth = healthData.reduce((sum, h) => sum + ((h.liquidity + h.efficiency + h.participation) / 3), 0) / healthData.length;
    if (avgHealth < 0.5) {
      focusAreas.push({
        type: 'region_health_improvement',
        target: region,
        priority: 'high'
      });
    }
  });

  // Focus on high-risk items
  if (report.criticalRisks.length > 0) {
    focusAreas.push({
      type: 'risk_monitoring',
      target: 'high_risk_items',
      priority: 'high'
    });
  }

  // Focus on high-opportunity areas
  if (report.topOpportunities.length > 10) {
    focusAreas.push({
      type: 'opportunity_tracking',
      target: 'top_opportunities',
      priority: 'medium'
    });
  }

  return focusAreas;
}

function extractPriorityItems(report) {
  return report.topOpportunities.slice(0, 10).map(opp => opp.itemId);
}

